import Teachersidebar from "./Teachersidebar";
import { useState,useEffect, use } from "react";
import axios from "axios";  
import { useParams } from "react-router-dom";
const baseURL="http://12.0.0.1:8000/api";
function Editcourse(){
    const[cats,setCats]=useState([]);
    const[courseData,setCourseData]=useState({
        category:'',
        title:'',
        description:'',
        featured_image:'',
        techs:'',
    }); 
    const courseId=useParams().course_id; 
    
    useEffect(()=>{
        try{
            axios.get(baseURL+"/category").then((response)=>{
                setCats(response.data);
                //console.log(response.data);
            });
        }
        catch(error){
            console.log(error);
        }
    try{
        axios.get(baseURL+"/teacher-course-detail/"+courseId).then((response)=>{
            setCourseData({
                category:response.data.category,
                title:response.data.title,
                description:response.data.description,
                featured_image:response.data.featured_image,
                techs:response.data.techs,
            });
            //console.log(response.data);
        });
    }
    catch(error){
        console.log(error);
    }},[])

   //console.log("Course ID:", courseId);
    // useEffect(()=>{
    //     try{    
    //         axios.get(baseURL+"/teacher-course-detail/"+courseId).then((response)=>{
    //             setCourses(response.data);
    //             console.log(response.data);
    //         });}
    //     catch(error){
    //         console.log(error);
    //     }},[])
        const handleChange=(event)=>{
            setCourseData({
                ...courseData, 
                [event.target.name]:event.target.value
            });
        }
        const handleFileChange=(event)=>{
            setCourseData({
                ...courseData, 
                [event.target.name]:event.target.files[0]
            });
        }
        const handleSubmit=(event)=>{
            event.preventDefault();
            const teacherId=localStorage.getItem('teacherId');
            const formData=new FormData();
            formData.append('teacher',teacherId);   
            formData.append('title',courseData.title);
            formData.append('description',courses.description);
            formData.append('featured_image',courses.featured_image);
            try{    
                axios.put(baseURL+"/teacher-course-detail/"+courseId,formData).then((response)=>{
                    alert("Course updated successfully");
                });}
            catch(error){
                console.log(error);
            }   
        }

    return(
        <div className="container mt-4">
            <div className="row">   
                <aside className="col-md-3">
                    <Teachersidebar></Teachersidebar>
                </aside>        
                <section className="col-md-9">  
                    <div className="card">
                        <h5 className="card-header">Edit Course</h5>        
                        <div className="card-body"> 
                            <form>  
                                <div className="mb-3">
                                    <label  className="form-label">Course Title</label>
                                    <input type="text" className="form-control"  />     
                                </div>  
                                <div className="mb-3">
                                    <label  className="form-label">Course Description</label>
                                    <textarea className="form-control" rows="5"></textarea>     
                                </div>  
                                <div className="mb-3">
                                    <label  className="form-label">Featured Image</label>
                                    <input type="file" className="form-control"  />     
                                </div>  
                                <button type="submit" className="btn btn-primary">Update Course</button>
                            </form>
                        </div>
                    </div>
                </section>  
            </div>
        </div>
    );

}
export default Editcourse;
